interface Element {
  void accept(Visitor v);
}

final class Paragraph implements Element {
  final String text;
  Paragraph(String text) { this.text = text; }
  @Override public void accept(Visitor v) { v.visitParagraph(this); }
}

final class Image implements Element {
  final String url; final int width; final int height;
  Image(String url, int w, int h) { this.url = url; this.width = w; this.height = h; }
  @Override public void accept(Visitor v) { v.visitImage(this); }
}

final class TableNode implements Element {
  final int rows; final int cols;
  TableNode(int rows, int cols) { this.rows = rows; this.cols = cols; }
  @Override public void accept(Visitor v) { v.visitTable(this); }
}

interface Visitor {
  void visitParagraph(Paragraph p);
  void visitImage(Image i);
  void visitTable(TableNode t);
}

final class XmlExportVisitor implements Visitor {
  final StringBuilder out = new StringBuilder();
  @Override public void visitParagraph(Paragraph p) {
    out.append("<p>").append(escape(p.text)).append("</p>");
  }
  @Override public void visitImage(Image i) {
    out.append("<img src=\"").append(i.url).append("\"/>");
  }
  @Override public void visitTable(TableNode t) {
    out.append("<table rows=\"").append(t.rows).append("\"/>");
  }
  private static String escape(String s) { return s.replace("&", "&amp;"); }
}

final class RenderCostVisitor implements Visitor {
  long costCents = 0;
  @Override public void visitParagraph(Paragraph p) { costCents += p.text.length() / 10; }
  @Override public void visitImage(Image i) { costCents += (long) i.width * i.height / 1000; }
  @Override public void visitTable(TableNode t) { costCents += (long) t.rows * t.cols * 5; }
}

